def solve(a: int, L: int) -> int:
    import math

    # Calculate the modular multiplicative inverse using the extended Euclidean algorithm
    def extended_gcd(a, b):
        if a == 0:
            return (b, 0, 1)
        else:
            gcd, x, y = extended_gcd(b % a, a)
            return (gcd, y - (b // a) * x, x)

    gcd, x, _ = extended_gcd(a, L)

    # If the gcd is not 1, it means that a and L are not coprime
    if gcd!= 1:
        raise ValueError("a and L must be coprime")

    # Return the modular multiplicative inverse
    return x % L

